import{Ht as e,Rt as t,dt as n,gt as r,mt as i,n as a}from"./chunks/framework.BkIgthgQ.js";var o=JSON.parse(`{"title":"技术白皮书","description":"改默认分支前的域模型：对象分层、唯一实现点与 leftover 404。可独立阅读。","frontmatter":{"title":"技术白皮书","description":"改默认分支前的域模型：对象分层、唯一实现点与 leftover 404。可独立阅读。"},"headers":[],"relativePath":"contribute/whitepaper.md","filePath":"contribute/whitepaper.md","lastUpdated":1790057721000}`),s={name:`contribute/whitepaper.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="技术白皮书" tabindex="-1">技术白皮书 <a class="header-anchor" href="#技术白皮书" aria-label="Permalink to “技术白皮书”">​</a></h1><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to “摘要”">​</a></h2><p>KiriVers 是自托管的<strong>更新目录与分发</strong>进程：一份 PostgreSQL 目录，两个 HTTP 平面。客户端平面（默认 <code>:8080</code>）对软件客户端提供原生 JSON 与九种商店 feed；管理平面（默认 <code>:8081</code>）托管 Vue 管理台 SPA 与 CI。两条客户端协议共享 <code>internal/service/update.SelectTarget</code> 选目标口径（列表型 feed 经 <code>AnonymousVisible</code> 投影，禁止分叉）。</p><p>发布单位是 <strong>Version</strong>（整数构建号与 SemVer 双编号、changelog、渠道、LTS / 关键 / 灰度）。可下载切片是 <strong>Version Line</strong>：同一 Version 在 <code>(os, arch)</code> 上的行，<strong>没有自己的版本号</strong>。产物键 <code>{slug}/{sha256}</code>；浏览器上传 <code>direct_s3</code> 恒为 <code>false</code>。</p><p>本页是改默认分支前的<strong>域模型</strong>：对象分层、唯一实现点、必须保持 404 的 leftover。运维步骤见功能指南；包树与启动链见 <a href="./architecture">运行架构</a>。</p><h2 id="问题与定位" tabindex="-1">问题与定位 <a class="header-anchor" href="#问题与定位" aria-label="Permalink to “问题与定位”">​</a></h2><p>要解决的是：把<strong>二进制安装包、固件镜像或多文件目录</strong>按渠道与平台发给已安装的客户端，并在需要时走差量或打包，而不是用 git 做源码协作。</p><table tabindex="0"><thead><tr><th>在范围内</th><th>不在范围内</th></tr></thead><tbody><tr><td>自托管目录、原生 check / 下载、商店 feed、灰度 allowlist、管理台与 CI 发版</td><td>git 托管、代码评审、CI 构建农场</td></tr><tr><td>单文件二进制差量、多文件 integrity + 动态打包</td><td>各商店上架审核、系统软件源</td></tr><tr><td>公开对象存储上的产物；私有后端上的 GeoIP</td><td>用管理平面 <code>GET /</code> 托管本站文档</td></tr></tbody></table><p>不是 git。不上架 App Store / Play / Microsoft Store。不是 APT / RPM / Flatpak 源。官方 SDK 只封装原生 JSON，不读 feed。</p><h2 id="运行形态" tabindex="-1">运行形态 <a class="header-anchor" href="#运行形态" aria-label="Permalink to “运行形态”">​</a></h2><p>一个 <code>kirivers</code> / <code>kirivers server</code> 进程、两套 Gin。装配顺序：三份 YAML → logger → PostgreSQL → storage → cache → 双 Gin → job worker（细节 <a href="./architecture">运行架构</a>）。</p><table tabindex="0"><thead><tr><th>平面</th><th>默认地址</th><th>职责</th></tr></thead><tbody><tr><td>客户端</td><td><code>:8080</code></td><td><code>POST .../update/check</code>、changelog、pack、商店 listing、遥测、公告</td></tr><tr><td>管理</td><td><code>:8081</code></td><td>SPA、管理 CRUD、CI <code>POST .../ci/releases</code></td></tr></tbody></table><p>管理平面在 <code>ClientProxyURL</code> 已设置时，把 <code>/api/v1/projects/**</code> <strong>反代</strong>到本进程客户端监听。空 <code>ClientProxyURL</code> 仅测试：这些路径在管理面是 JSON <code>NOT_FOUND</code>。Vite 开发代理必须把 <code>/api/v1/projects</code> 写在 <code>/api</code> <strong>之前</strong>。</p><p>管理台文件：Gin <strong>NoRoute</strong>（<code>frontend/embed.go</code> <code>//go:embed all:dist</code>）。禁止 <code>gin.Static</code> / <code>StaticFS</code>。优先级：非空 <code>static_dir</code> 且磁盘有 <code>index.html</code> → 磁盘；否则内嵌 FS 有 <code>index.html</code> → embed；<code>static_dir: &quot;&quot;</code> → 关 UI。</p><p>探活只有 <code>GET /api/v1/health</code>。健康 JSON 里的 <code>ready</code> 探 PostgreSQL 与对象存储，<strong>不含</strong> Redis。<code>GET /api/v1/ready</code> 未注册。</p>`,15),r(d,{code:`flowchart%20TB%0A%20%20subgraph%20proc%20%5Bkirivers%20process%5D%0A%20%20%20%20C%5BGin%20client%20%3A8080%5D%0A%20%20%20%20A%5BGin%20admin%20%3A8081%5D%0A%20%20%20%20S%5Bservice%5D%0A%20%20%20%20C%20--%3E%20S%0A%20%20%20%20A%20--%3E%20S%0A%20%20%20%20A%20--%3E%7Cproxy%20%2Fapi%2Fv1%2Fprojects%7C%20C%0A%20%20end%0A%20%20SPA%5BAdmin%20SPA%20disk%20or%20embed%5D%0A%20%20Vite%5BVite%20%3A3000%5D%0A%20%20Native%5BNative%20SDK%20clients%5D%0A%20%20Feeds%5BStore%20updaters%5D%0A%20%20A%20--%3E%7CNoRoute%20GET%2FHEAD%7C%20SPA%0A%20%20Vite%20--%3E%7C%2Fapi%2Fv1%2Fprojects%20first%7C%20C%0A%20%20Vite%20--%3E%7C%2Fapi%7C%20A%0A%20%20Native%20--%3E%20C%0A%20%20Feeds%20--%3E%20C%0A%20%20SPA%20--%3E%7Cpreview%20via%20proxy%7C%20A%0A`}),o[1]||=i(`<h2 id="对象模型" tabindex="-1">对象模型 <a class="header-anchor" href="#对象模型" aria-label="Permalink to “对象模型”">​</a></h2><p>身份：<code>uuid</code>、<code>slug</code>、未过期别名是 <code>project_ref</code>。控制台 <code>name</code> 是 Unicode 标题，<strong>不是</strong> <code>project_ref</code>，也不出现在客户端 <code>ProjectPublic</code>、check 或 feed。</p><p><code>internal/model</code> 分层（不展开包树）：</p><table tabindex="0"><thead><tr><th>类型</th><th>含义</th></tr></thead><tbody><tr><td><code>Project</code></td><td>目录根；<code>compare_engine</code>、<code>device_id</code> 策略、存储前缀</td></tr><tr><td><code>Channel</code></td><td>渠道 slug、<code>stability_rank</code>、unlisted、可选 <code>X-Channel-Token</code></td></tr><tr><td>平台矩阵</td><td><code>(os, arch)</code> 行；该对首次发布后 <code>package_type</code> 锁定</td></tr><tr><td><code>HwRev</code></td><td>硬件代号；feed / 匿名 check 用默认变体</td></tr><tr><td><code>Version</code></td><td>双编号、changelog、渠道、LTS / 关键 / 灰度、<code>min_source_version</code></td></tr><tr><td><code>VersionLine</code></td><td><code>(version, os, arch)</code> 切片；<code>min_os</code> / <code>min_api_level</code> 在线上，不在矩阵列</td></tr><tr><td><code>Artifact</code></td><td><code>full</code> / <code>store_full</code> / <code>delta</code> / <code>patch</code> / <code>file</code>；键 <code>{slug}/{sha256}</code></td></tr></tbody></table><p>Version <strong>拥有</strong> changelog、渠道、LTS、关键、灰度。Version Line <strong>没有</strong>独立版本号。</p>`,5),r(d,{code:`flowchart%20TB%0A%20%20P%5BProject%5D%0A%20%20Ch%5BChannel%5D%0A%20%20Mx%5BPlatform%20matrix%5D%0A%20%20Hw%5BHwRev%5D%0A%20%20V%5BVersion%5D%0A%20%20VL%5BVersion%20Line%5D%0A%20%20Art%5BArtifact%5D%0A%20%20P%20--%3E%20Ch%0A%20%20P%20--%3E%20Mx%0A%20%20P%20--%3E%20Hw%0A%20%20P%20--%3E%20V%0A%20%20V%20--%3E%20VL%0A%20%20Mx%20-.-%3E%20VL%0A%20%20VL%20--%3E%20Art%0A`}),o[2]||=i(`<h2 id="版本身份与比较" tabindex="-1">版本身份与比较 <a class="header-anchor" href="#版本身份与比较" aria-label="Permalink to “版本身份与比较”">​</a></h2><p>每个 Version 可同时有整数构建号与 SemVer。项目 <code>compare_engine</code> 为 <code>integer</code> 或 <code>semver</code>，决定排序与选目标；另一个编号只作显示与协议映射。<code>+build</code> <strong>不参与</strong>唯一性与顺序。首次 <strong>published</strong> 之后引擎不可改（<code>COMPARE_ENGINE_IMMUTABLE</code>）。</p><p>解析 <code>current_version</code>（<code>ParseVersionRef</code>）：全数字 → 整数身份；否则 SemVer 2.0，去掉前导 <code>v</code> 与 <code>+build</code>。无法解析 → 400 <code>ENGINE_MISMATCH</code>，<strong>不得</strong>当成 <code>0</code>。能解析但目录中没有 → 404 <code>VERSION_NOT_FOUND</code>。定位到 Version 之后，比较<strong>只</strong>看 <code>compare_engine</code>。</p><p>商店 adapter 按协议固定映射两个编号（例如 Sparkle 的 <code>sparkle:version</code> 与 <code>sparkle:shortVersionString</code>），<strong>不</strong>跟显示键或 <code>compare_engine</code> 走。协议字段见 <a href="./store">商店适配器</a>。</p><p>管理台列表卡片的 <code>latest_version</code> 走 <code>update.CompareVersions</code>（published + deprecated），<strong>禁止</strong>调用 <code>SelectTarget</code>。</p><h2 id="两条客户端协议" tabindex="-1">两条客户端协议 <a class="header-anchor" href="#两条客户端协议" aria-label="Permalink to “两条客户端协议”">​</a></h2><ol><li><strong>原生 JSON</strong>（官方 SDK 唯一路径）：<code>POST /api/v1/projects/:ref/update/check</code>。请求体必填 <code>current_version</code>、<code>os</code>、<code>arch</code>；可选 <code>channel</code>、<code>hw_rev</code>、<code>os_version</code>、<code>device_id</code>、<code>capabilities</code>、<code>accepted_delta_algos</code>。能力位：<code>full_package</code> / <code>file_list</code> / <code>patch_package</code> / <code>binary_delta</code>。未声明时只广告 <code>full_package</code>。遗留查询 <code>protocol_version</code> <strong>忽略</strong>；无协议头。<code>GET .../update/check</code> 未注册（404，无 301）。</li><li><strong>商店 feed</strong>：listing 作用域 <code>GET .../store/{protocol}/{listing_slug}/{doc}</code>。九种 adapter：<code>sparkle</code>、<code>electron</code>、<code>tauri</code>、<code>squirrel</code>、<code>clickonce</code>、<code>appimage</code>、<code>winget</code>、<code>msix</code>、<code>fdroid</code>。缺 listing slug 为<strong>纯文本 404</strong>。SDK <strong>不</strong>读 feed。HTTP 与 enclosure 规则见 <a href="./store">商店适配器</a>。</li></ol><p>原生 check 调用 <code>SelectTarget</code>。列表型 feed 用 <code>store.AnonymousVisible</code> 投影<strong>同一匿名口径</strong>（无 <code>device_id</code>、默认 <code>hw_rev</code>、仅 <code>GrayIsComplete</code>），不得另写选目标；单目标动态端点（如 Tauri）直接调用 <code>SelectTarget</code>。</p><p>Check <strong>不是</strong> CDN 对象：200/204 使用 <code>private, max-age=0, must-revalidate</code>（含匿名且灰度已完成）。<code>cache_s_maxage_seconds</code> <strong>不</strong>作用在 check。</p><div class="danger custom-block"><p class="custom-block-title">错误</p><p><code>GET /api/v1/projects/:ref/update/check</code> 作为现行检查更新方法。</p></div><div class="tip custom-block"><p class="custom-block-title">正确</p><p><code>POST /api/v1/projects/:ref/update/check</code>。遗留 GET 保持未注册 404。</p></div><div class="danger custom-block"><p class="custom-block-title">错误</p><p><code>GET /api/v1/projects/:ref/store/sparkle/appcast.xml</code>（无 listing slug）。</p></div><div class="tip custom-block"><p class="custom-block-title">正确</p><p><code>GET /api/v1/projects/:ref/store/{protocol}/{listing_slug}/{doc}</code>。缺 listing 纯文本 404。</p></div>`,13),r(d,{code:`flowchart%20TB%0A%20%20POST%5BPOST%20%2Fupdate%2Fcheck%20optional%20device_id%5D%0A%20%20LIST%5BGET%20listing%20feed%20anonymous%5D%0A%20%20TAU%5BSingle-target%20feed%20e.g.%20Tauri%5D%0A%20%20ST%5Bupdate.SelectTarget%5D%0A%20%20AV%5Bstore.AnonymousVisible%5D%0A%20%20POST%20--%3E%20ST%0A%20%20TAU%20--%3E%20ST%0A%20%20LIST%20--%3E%20AV%0A%20%20ST%20--%3E%20R200%5B200%20one%20target%5D%0A%20%20ST%20--%3E%20R204%5B204%5D%0A%20%20ST%20--%3E%20R409%5B409%5D%0A%20%20AV%20--%3E%20ITEMS%5Bpublished%20ready%20default-hw%20GrayIsComplete%5D%0A`}),o[3]||=i('<h2 id="目标选择与生命周期" tabindex="-1">目标选择与生命周期 <a class="header-anchor" href="#目标选择与生命周期" aria-label="Permalink to “目标选择与生命周期”">​</a></h2><p>Version 状态：<code>draft</code> → <code>published</code> → <code>deprecated</code> / <code>revoked</code>。<code>draft</code> 对客户端不可见。<code>deprecated</code> 不作为自动升级目标，但仍可查询或下载。<code>revoked</code> 禁止下载，允许安全降级。<code>is_lts</code> 可事后设置。<code>is_critical</code> 发布即 <code>GrayIsComplete</code>，不能进灰度。</p><p>Version Line 就绪后才进入目录。<code>packs_ready_at</code> 由系统 <code>auto_delta</code> 预热（渠道 × <code>delta_source_count</code>）盖戳；未盖戳 → check / feed <code>VERSION_NOT_VISIBLE</code>。客户端动态打包 <strong>不得</strong>改写该戳。</p><p><strong>原生</strong>选目标的唯一实现：<code>internal/service/update.SelectTarget</code>（<code>select.go</code>）。列表型 feed 走 <code>store.AnonymousVisible</code>（同源匿名口径，不跑完整 SelectTarget）。公告匹配与管理台 latest <strong>禁止</strong>调用 <code>SelectTarget</code>。</p><p>Hop：只读 <code>Version.MinSourceVersion</code>。胜者是比较键最高的候选；若当前低于该胜者的门槛，沿 <code>min_source</code> 链改写目标（Published + 就绪线 + hw + 渠道允许），最多 <strong>8</strong> 跳。缺失 / 未就绪 / 环 / 超过 8 → 409 <code>INTERMEDIATE_UNAVAILABLE</code>。<strong>不要</strong>跳过被门槛挡住的最新候选去选次高版本。</p><p>当前线自身的 <code>min_os</code> / <code>min_api_level</code> 未满足 → 409 <code>MIN_OS_NOT_MET</code>（<code>lineMeetsOS</code>，只读 Version Line 列）。候选级不满足则静默跳过。目录中未知的 <code>current_version</code> → 404 <code>VERSION_NOT_FOUND</code>。吊销且无安全目标 → 409 <code>NO_SAFE_TARGET</code>。无更新 → <strong>204</strong>（仍带 ETag）。</p><h2 id="渠道、token-与灰度" tabindex="-1">渠道、Token 与灰度 <a class="header-anchor" href="#渠道、token-与灰度" aria-label="Permalink to “渠道、Token 与灰度”">​</a></h2><p>系统渠道 <code>stability_rank</code>：alpha 10、beta 20、stable 30。跨渠道只允许升到更稳（或同级按比较键）。Unlisted：仅当客户端<strong>当前</strong>渠道 slug 或查询 <code>channel=</code> 等于该 slug 时可用，否则跳过，不 404 整次 check。</p><p><code>X-Channel-Token</code> 与项目 <code>X-Project-Token</code> 不同。Token 保护渠道：头不匹配则 <code>channelAllowedForUpgrade</code> <strong>跳过该渠道</strong>，其它公开渠道仍可 200；没有其它更新则 204。Check 上错误 Token <strong>不是</strong> 401/403。明文不得进 ETag、日志或缓存键。Changelog 路径上 Token 不匹配是 404。</p><p>原生带 <code>device_id</code> 的灰度命中：<code>grayHitFor</code> = allowlist，直到 <code>Version.GrayIsComplete()</code>（<code>is_critical</code> 或 <code>gray_completed_at</code>）。旋钮 <code>gray_start_percent</code> / <code>gray_step_percent</code> / <code>gray_interval_seconds</code> 经 <code>GrayCoverage</code> 计算目标名册规模并驱动 admission 补员，<strong>不</strong>进入 <code>grayHitFor</code>。空名册立即完成。<code>pkg/grayutil</code> 是遗留包，check <strong>不得</strong>调用。匿名与 feed <strong>只</strong>看 <code>GrayIsComplete</code>；未完成的灰度对 Sparkle / electron 等不可见。</p><div class="danger custom-block"><p class="custom-block-title">错误</p><p>用 HMAC 百分比桶决定灰度是否命中。</p></div><div class="tip custom-block"><p class="custom-block-title">正确</p><p>有 <code>device_id</code>：allowlist，直至 <code>GrayIsComplete</code>。匿名 / feed：只看 <code>GrayIsComplete</code>。</p></div><h2 id="产物与增量" tabindex="-1">产物与增量 <a class="header-anchor" href="#产物与增量" aria-label="Permalink to “产物与增量”">​</a></h2><p>下载 URL 的唯一构造：<code>update.PackageDownloadURL</code> → <code>/api/v1/projects/{slug}/packages/{64-hex}</code>（单节点或 <code>cluster.download=local</code>）。集群 S3-direct 时同一助手改为公开 <code>{slug}/{sha256}</code> 对象 URL。Feed enclosure 必须用同一助手。JSON <code>file_name</code> 是未签名显示名。<code>GET /artifacts/{id}/{filename}</code> 未注册。</p><p>单文件差量能力 <code>binary_delta</code>：<code>internal/delta</code> 三种算法（bsdiff、xdelta3、hdiffpatch）。服务端 <code>hdiffpatch</code> 经 CGO 链接 libHDiffPatch，生成未压缩 <code>HDIFF13&amp;</code>，运行时不 exec PATH 上的 CLI。<code>bsdiff</code> / <code>xdelta3</code> 仍为纯 Go。Magic 与分流见 <a href="./delta">差量引擎</a>。Go SDK 仍 <code>CGO_ENABLED=0</code>。</p><p>多文件：客户端先 integrity，再 <code>POST /update/pack</code>（入队与轮询同一 URL）。未压缩 Manifest 合计超过 <code>dynamic_pack.max_bytes</code>，或 needed 体积相对全量 Manifest 过大 → HTTP <strong>200</strong> <code>status=full_package</code>，不是 400，也不把管理 <code>job_id</code> 暴露给客户端。原生 hash-root zip 是 <code>kind=full</code>；商店 <code>line_full</code> 必须是 <code>kind=store_full</code>（路径 zip）。多文件线缺少 <code>store_full</code> 则跳过该版本，<strong>禁止</strong>拿 <code>full</code> 冒充 <code>line_full</code>。</p><p>浏览器预签名 <code>direct_s3</code> 恒为 <code>false</code>；禁止对未知 S3 键裸 PUT。</p><h2 id="日志、公告与媒体" tabindex="-1">日志、公告与媒体 <a class="header-anchor" href="#日志、公告与媒体" aria-label="Permalink to “日志、公告与媒体”">​</a></h2><p>原生 changelog <strong>只</strong>在 <code>GET .../changelog/:channel/:os/:arch</code>。Check 200 <strong>没有</strong> <code>changelog</code> / <code>changelog_versions</code>。Check 的目录 ETag 不含 Version changelog 正文。路径 channel 必填；Token 不匹配 → 404。Markdown <code>${site_url}</code> 按 <strong>RequestOrigin</strong> 展开（忽略 Referer）。</p><p>公告是独立资源：<code>GET .../announcements</code>，匹配函数只有 <code>announcementMatches</code>（七种合法 scope，Version 绑 UUID）。空匹配是 200 <code>{announcements:[]}</code>，不是 204。禁止写入 check / changelog / feed，也禁止用 <code>SelectTarget</code> 决定公告。公告 <code>${site_url}</code> 仍按 Referer 展开。</p><p>媒体：管理上传进 <code>storage.Backend</code>（<code>media/…</code>）；客户端按 UUID 公开 GET。文档里不放预签名 URL。</p><div class="danger custom-block"><p class="custom-block-title">错误</p><p>在 check 200 正文里带 <code>changelog</code> 或 <code>changelog_versions</code>。</p></div><div class="tip custom-block"><p class="custom-block-title">正确</p><p>changelog 走 <code>GET .../changelog/:channel/:os/:arch</code>。公告走独立 GET。</p></div><h2 id="存储、cdn-与集群" tabindex="-1">存储、CDN 与集群 <a class="header-anchor" href="#存储、cdn-与集群" aria-label="Permalink to “存储、CDN 与集群”">​</a></h2><p>进程有两类对象后端：</p><table tabindex="0"><thead><tr><th>后端</th><th>键</th><th>用途</th></tr></thead><tbody><tr><td>公开</td><td><code>{slug}/{sha256}</code></td><td>安装包、差量、patch、商店 zip</td></tr><tr><td>私有</td><td><code>geoip/{id}/…</code></td><td>GeoIP MMDB；禁止写到公开桶</td></tr></tbody></table><p>管理 API 把项目 <code>storage_visibility</code> <strong>锁成</strong> <code>public</code>；PATCH <code>private</code> → 400。代码里仍可能有历史 private 行与 local-proxy 路径，控制台没有「私有托管产物」开关。</p><p>Check 响应不得当作公开 CDN 对象（见上节 Cache-Control）。<code>ClusterActive</code> = <code>storage.driver=s3</code> <strong>且</strong> <code>cache.driver=redis</code>。local-proxy（<code>cluster.download=local</code>）下 check 与 feed 使用 <code>private, no-store</code>，避免把节点副本可见性送进共享 CDN。<code>GET /packages</code> 优先本地副本。</p><p><code>/health</code> 的 <code>ready</code>：DB Ping + 公开（及已打开的私有）后端 Head <code>.ready</code>。Redis 运行时回退不是 <code>ready=false</code>。</p><h2 id="管理平面、ci-与控制台" tabindex="-1">管理平面、CI 与控制台 <a class="header-anchor" href="#管理平面、ci-与控制台" aria-label="Permalink to “管理平面、CI 与控制台”">​</a></h2><p>四类凭据不要混用：实例 / 平台管理员会话（2FA / Passkey）、项目成员、CI Token（<code>POST .../ci/releases</code>）、项目 Token（客户端 <code>require_client_token</code>）。渠道 Token 只跳过渠道，不是项目鉴权。</p><p>控制台是域表面，不是第二套协议。CRUD 走管理平面 SDK（<code>@/api/generated</code>）。check / integrity / 公告<strong>预览</strong>走客户端平面 SDK（<code>@/api/generated-client</code>），经管理监听上的 <code>/api/v1/projects/**</code> 反代。不要再造第三个 HTTP 客户端。</p><p>域规则：</p><ul><li>控制台 <code>name</code> ≠ <code>project_ref</code>。</li><li>版本写入 <code>changelog_i18n</code>；不得丢掉额外 locale 键。</li><li>灰度 UI：GET allowlist（<code>client_ids</code>）+ 旋钮，不是百分比 HMAC 控件。</li><li>预览 check 是 <strong>POST</strong> <code>checkUpdate</code>。Integrity 对话框没有 limit 控件。</li><li><code>direct_s3</code> 恒 false。</li><li>平台 combobox 使用 slug ∪ <code>COMMON_*</code>，不用 <code>entry.name</code> 当 os/arch。</li></ul><p>操作步骤与 SFC / yarn 日常循环见 <a href="./frontend">管理台前端</a>。平台管理员表面：admins、GeoIP、nodes、security；项目表面：总览、设置、渠道、矩阵、hw-revs、语言、公告、Token、发版、审计、客户端、版本与灰度。</p><h2 id="鉴权、签名与隐私" tabindex="-1">鉴权、签名与隐私 <a class="header-anchor" href="#鉴权、签名与隐私" aria-label="Permalink to “鉴权、签名与隐私”">​</a></h2><p>JSON 错误走 <code>pkg/response</code> 信封 <code>error.code</code>。商店缺 listing <strong>例外</strong>：纯文本 404，不是该信封。</p><p>原生响应签名（<code>pkg/signature.SignPayload</code>）覆盖 <code>integer</code>、<code>semver</code>、<code>root_hash</code>、<code>package_url</code>、<code>size</code>、<code>sha256</code> 字段，不是文件字节。Sparkle <code>edSignature</code> 是 enclosure <strong>文件字节</strong>上的 Ed25519，与原生 payload 签名不是同一条。</p><p><code>device_id</code> 策略：<code>hashed</code>（默认，入库为项目 <code>DeviceSecret</code> 派生的摘要）、<code>raw</code>（不推荐）、<code>none</code>（不插 <code>clients</code> 行，等同缺 <code>device_id</code>；空名册使灰度直接完成）。摘要密钥不出现在任何 API JSON。应用日志只写 Fingerprint，不写原始 <code>device_id</code>。</p><p>在线是 <code>POST .../clients/report</code> → <code>{ip, country_code, region_code, geo_i18n}</code>。遗留 <code>POST .../clients/login</code> 保持 404。<code>device_id_policy=none</code> 时 report 为 400。</p><h2 id="官方-sdk-边界" tabindex="-1">官方 SDK 边界 <a class="header-anchor" href="#官方-sdk-边界" aria-label="Permalink to “官方 SDK 边界”">​</a></h2><p>每种语言一条孤儿分支 <code>sdk/&lt;lang&gt;</code>，在<strong>独立 git worktree</strong> 里维护。Go / PHP / Swift 的 <code>sdk/go</code> 等是指针 README；完整源码在 <code>sdk/go-src</code> / <code>sdk/php-src</code> / <code>sdk/swift-src</code>，再同步到独立发布仓。默认分支 <strong>没有</strong> <code>sdk/</code> 目录，也不合并任何 <code>sdk/*</code>。</p><p>SDK 只封装原生 JSON。语言 agent <strong>不得</strong>改默认分支（含 <code>internal/</code>）；若服务端行为错误，在语言 worktree 写 <code>BACKEND_ISSUE.md</code>。安装坐标见 <a href="/api/sdk/">API → SDK</a>。维护者分支规则见 <a href="./sdk">SDK 源码分支</a>。</p><h2 id="明确非范围与禁止复活" tabindex="-1">明确非范围与禁止复活 <a class="header-anchor" href="#明确非范围与禁止复活" aria-label="Permalink to “明确非范围与禁止复活”">​</a></h2><p>产品不做：git 替代、封闭商店审核、APT/RPM/Flatpak、再写一套更新器、把文档站挂在管理 <code>GET /</code>、未合并的进程内 CGO 差量。</p><p>禁止分叉的实现点：</p><table tabindex="0"><thead><tr><th>不变量</th><th>唯一 owner</th><th>禁止</th></tr></thead><tbody><tr><td>原生选目标</td><td><code>update.SelectTarget</code></td><td>列表 feed 另写过滤；公告匹配；列表卡片 latest</td></tr><tr><td>列表 feed 投影</td><td><code>store.AnonymousVisible</code></td><td>adapter 内自写可见性；调用完整 <code>SelectTarget</code> 当列表</td></tr><tr><td>列表卡片 latest</td><td><code>update.CompareVersions</code>（published+deprecated）</td><td><code>SelectTarget</code></td></tr><tr><td>原生灰度命中</td><td>allowlist 直至 <code>Version.GrayIsComplete</code></td><td><code>pkg/grayutil</code>、HMAC、<code>rollout_percent</code></td></tr><tr><td>Check 渠道 Token</td><td>跳过渠道，从不 401/403</td><td>把错误 <code>X-Channel-Token</code> 当鉴权失败</td></tr><tr><td>公告匹配</td><td><code>announcementMatches</code></td><td>写入 check；调用 <code>SelectTarget</code></td></tr><tr><td>原生 changelog</td><td><code>GET .../changelog/:channel/:os/:arch</code></td><td>check 200 的 <code>changelog*</code></td></tr><tr><td>产物 HTTP URL</td><td><code>update.PackageDownloadURL</code></td><td><code>/artifacts/{id}/{filename}</code>；未知键 PresignPut</td></tr><tr><td>Feed enclosure</td><td>与 check 同一助手</td><td>adapter 自建 URL</td></tr><tr><td>商店 <code>line_full</code></td><td><code>kind=store_full</code></td><td>hash-root <code>kind=full</code></td></tr><tr><td>原生打包超限</td><td>200 <code>status=full_package</code></td><td>400；客户端看到管理 <code>job_id</code></td></tr><tr><td>JSON 错误</td><td><code>pkg/response</code></td><td>商店缺 listing（纯文本 404）</td></tr><tr><td>管理台文件</td><td>NoRoute；<code>frontend/embed.go</code></td><td><code>gin.Static</code> / <code>StaticFS</code></td></tr><tr><td>OpenAPI</td><td><code>openapi.admin.json</code> / <code>openapi.client.json</code></td><td>手改 <code>generated*</code></td></tr><tr><td>SPA 客户端预览</td><td><code>@/api/generated-client</code> + <code>/api/v1/projects/**</code> 反代</td><td>第三个 HTTP 客户端</td></tr></tbody></table><p>必须保持未注册（404，无 301）的 leftover：</p><table tabindex="0"><thead><tr><th>路径</th><th>现行替代</th></tr></thead><tbody><tr><td><code>GET .../update/check</code></td><td><code>POST .../update/check</code></td></tr><tr><td><code>POST .../clients/login</code></td><td><code>POST .../clients/report</code>（仅 geo 四字段）</td></tr><tr><td><code>/store/{protocol}/{doc}</code>（无 listing slug）</td><td><code>/store/{protocol}/{listing_slug}/{doc}</code></td></tr><tr><td><code>GET /api/v1/ready</code></td><td><code>GET /api/v1/health</code>（<code>ready</code> 在 JSON 内，不含 Redis）</td></tr></tbody></table><p>POST check 上遗留查询 <code>protocol_version</code> 忽略，不要重新做成协商头。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><table tabindex="0"><thead><tr><th>页</th><th>内容</th></tr></thead><tbody><tr><td><a href="./architecture">运行架构</a></td><td>启动链、NoRoute、<code>/api/v1/projects</code> 反代、探活</td></tr><tr><td><a href="./backend">后端分层</a></td><td>controller / service / repository</td></tr><tr><td><a href="./frontend">管理台前端</a></td><td>双 SDK、Vite 代理、yarn 循环</td></tr><tr><td><a href="./delta">差量引擎</a></td><td>三种算法与 magic</td></tr><tr><td><a href="./store">商店适配器</a></td><td>九协议 HTTP 与 enclosure</td></tr><tr><td><a href="./openapi">OpenAPI 契约</a></td><td>两份平面 JSON</td></tr><tr><td><a href="./sdk">SDK 源码分支</a></td><td><code>sdk/&lt;lang&gt;</code> worktree</td></tr><tr><td>功能指南</td><td><a href="/guide/features/channels">渠道</a>、<a href="/guide/features/gray">灰度</a>、<a href="/guide/features/incremental">增量</a> 等运维步骤</td></tr><tr><td><a href="/api/sdk/">API → SDK</a></td><td>语言安装</td></tr><tr><td>仓库 <code>.trellis/spec/</code></td><td>贡献者可执行契约（不是安装文档）</td></tr></tbody></table>',52)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};